// Risk sampler: uncertainty + stakes + random baseline (plain JS)
function sampleForReview(items) {
  const picked = [];
  for (const it of items) {
    const uncertain = it.confidence < 0.7;
    const stakes = it.money || it.external;
    const baseline = Math.random() < 0.05; // 5% random calibration slice
    if (uncertain || stakes || baseline) picked.push({ id: it.id, reason: uncertain ? "uncertain" : stakes ? "stakes" : "baseline" });
  }
  return picked;
}
// Reasons travel with samples: reviewers see WHY each item needs eyes.

