function sampleForReview(items) {
  const picked = [];
  for (const it of items) {
    const uncertain = it.confidence < 0.7;
    const stakes = !!(it.money || it.external);
    if (uncertain || stakes) picked.push({ id: it.id, reason: uncertain ? 'uncertain' : 'stakes' });
  }
  return picked;
}
const queue = [
  { id: 'a', confidence: 0.9 },
  { id: 'b', confidence: 0.5 },
  { id: 'c', confidence: 0.95, money: true },
  { id: 'd', confidence: 0.95 },
];
const picked = sampleForReview(queue);
console.log('picked=' + picked.map((p) => p.id).join(','));
console.log('reasons=' + picked.map((p) => p.reason).join(','));
console.log('coverage=' + picked.length + '/4');

